// Simple Astro Dodge game
// Canvas with id="game"
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;

  // Player ship
  const ship = { w: 40, h: 20, x: width / 2 - 20, y: height - 30, speed: 5 };

  // Asteroids
  const asteroids = [];
  let spawnTimer = 0;
  const spawnInterval = 90; // frames

  let gameOver = false;

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  function update() {
    if (gameOver) return;
    // Move ship
    if (keys.ArrowLeft) ship.x -= ship.speed;
    if (keys.ArrowRight) ship.x += ship.speed;
    ship.x = Math.max(0, Math.min(width - ship.w, ship.x));

    // Spawn asteroids
    if (spawnTimer <= 0) {
      const size = 20 + Math.random() * 30;
      asteroids.push({ x: Math.random() * (width - size), y: -size, size, speed: 2 + Math.random() * 3 });
      spawnTimer = spawnInterval;
    } else {
      spawnTimer--;
    }

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // Collision with ship
      if (
        a.x < ship.x + ship.w &&
        a.x + a.size > ship.x &&
        a.y < ship.y + ship.h &&
        a.y + a.size > ship.y
      ) {
        gameOver = true;
      }
      // Remove if off screen
      if (a.y > height) {
        asteroids.splice(i, 1);
        // lose condition if asteroid reaches bottom (optional extra)
        gameOver = true;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Draw ship
    ctx.fillStyle = 'cyan';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // Draw asteroids
    ctx.fillStyle = 'gray';
    for (const a of asteroids) {
      ctx.fillRect(a.x, a.y, a.size, a.size);
    }
    if (gameOver) {
      ctx.fillStyle = 'red';
      ctx.font = '30px sans-serif';
      ctx.fillText('Game Over', width / 2 - 80, height / 2);
    }
  }

  function loop() {
    if (!gameOver) {
      update();
    }
    draw();
    requestAnimationFrame(loop);
  }

  loop();
})();
